do $$
declare n int; v int;
begin
  select count(*) into n from public.opening_lines l join public.courses c on c.id = l.course_id
   where c.slug = 'italian-game' and l.popularitate_pe_rating ? 'chesscom' and l.popularitate_pe_rating ? 'lichess';
  select count(*) into v from public.opening_lines l join public.courses c on c.id = l.course_id,
         jsonb_array_elements(l.variante) e
   where c.slug = 'italian-game' and e ? 'popularitate_pe_rating';
  if n <> 8 or v <> 23 then
    raise exception 'Italiana: % capitole şi % variante cu procente pe rating; aşteptat 8 şi 23', n, v;
  end if;
end $$;
